window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-a2ad1dbe50fbb08e"]={"versions": [{"id": "FIG-a2ad1dbe50fbb08e", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">AUTOSAR-Komponentendiagramm / VFB-Architekturdiagramm im Kontext des AUTOSAR Software Component Template (TPS SoftwareComponentTemplate). Das Diagramm illustriert die zulässige Zusammenführung (Legal Merge) von Delegationskonnektoren (<code>DelegationSwConnector</code>) an einer Kompositionsgrenze (<code>CompositionSwComponentType</code>) hin zu einer externen Software-Komponente über einen <code>AssemblySwConnector</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Übergeordnete Komposition (<code>CompositionSwComponentType</code>)</strong>: Umschließt zwei interne Software-Komponenten-Prototypen und besitzt einen äußeren P-Port (<code>PPortPrototype</code>) mit der Daten-/Elementmenge <code>{A,B}</code> und der Eigenschaft <code>[single]</code>.</li>\n<li><strong>Interne Komponenten</strong>:</li>\n<li>Obere Komponente mit einem P-Port, der das Datenelement <code>{A}</code> bereitstellt.</li>\n<li>Untere Komponente mit einem P-Port, der das Datenelement <code>{B}</code> bereitstellt.</li>\n<li><strong>Externe Empfängerkomponente</strong>: Besitzt einen R-Port (<code>RPortPrototype</code>), der die Elementmenge <code>{A,B}</code> anfordert.</li>\n<li><strong>Konnektoren</strong>:</li>\n<li>Zwei interne Delegationskonnektoren (<code>DelegationSwConnector</code>), die von den internen Ports <code>{A}</code> bzw. <code>{B}</code> auf den gemeinsamen äußeren P-Port <code>{A,B}</code> gemergt werden.</li>\n<li>Ein Assembly-Konnektor (<code>AssemblySwConnector</code>), der den äußeren P-Port <code>{A,B}</code> mit dem externen R-Port <code>{A,B}</code> verbindet.</li>\n<li><strong>Bewertungssymbol</strong>: Ein Smiley-Icon symbolisiert die semantische und syntaktische Gültigkeit („legal“) dieser Konfiguration.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die internen Software-Komponenten senden disjunkte Teilmengen von Datenelementen (<code>{A}</code> bzw. <code>{B}</code>). Am gemeinsamen Port des umschließenden Typs werden diese Delegationen zu einer konsistenten Gesamtschnittstelle <code>{A,B}</code> zusammengeführt (<code>merge</code>). Von dort werden die aggregierten Daten über die Montageverbindung an die externe Empfängerkomponente weitergeleitet. Da die Elementmengen disjunkt sind (<code>{A} ∩ {B} = ∅</code>) und exakt der Schnittstelle des äußeren Single-Ports <code>{A,B}</code> entsprechen, tritt kein Schreibkonflikt auf.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Veranschaulicht die Regelungen für <code>DelegationSwConnector</code> an P-Ports mit <code>[single]</code>-Semantik. Ein Zusammenführen mehrerer Delegationspfade auf einen einzelnen äußeren P-Port ist zulässig, sofern jedes Datenelement der Port-Schnittstelle eindeutig durch genau eine interne Quelle bereitgestellt wird und die Vereinigung der internen Datenmengen die äußere Schnittstelle vollständig und überschneidungsfrei abdeckt. Entwickler und Autoren von AUTOSAR-Authoring-Tools müssen sicherstellen, dass bei <code>[single]</code> keine Mehrfachzuweisungen für identische Datenelemente innerhalb eines Merges entstehen.</p>"}, {"id": "FIG-5f7a785ef2ea9e41", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">AUTOSAR-Komponentendiagramm / VFB-Architekturdiagramm im Kontext des AUTOSAR Software Component Template (TPS SoftwareComponentTemplate). Das Diagramm stellt das zulässige Zusammenführen von Delegationskonnektoren (<code>DelegationSwConnector</code>) an einem äußeren P-Port mit <code>[nfold]</code>-Kommunikationssemantik innerhalb einer <code>CompositionSwComponentType</code> dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Übergeordnete Komposition (<code>CompositionSwComponentType</code>)</strong>: Umschließt zwei interne Komponenten und stellt einen äußeren P-Port mit der Elementmenge <code>{A,B,C}</code> und der Kennzeichnung <code>[nfold]</code> bereit.</li>\n<li><strong>Interne Komponenten</strong>:</li>\n<li>Obere Komponente mit P-Port <code>{A,B}</code>.</li>\n<li>Untere Komponente mit P-Port <code>{B,C}</code>.</li>\n<li><strong>Externe Empfängerkomponente</strong>: Besitzt einen R-Port mit der Schnittstelle <code>{A,B,C}</code>.</li>\n<li><strong>Konnektoren</strong>:</li>\n<li>Zwei Delegationskonnektoren, die von den internen P-Ports <code>{A,B}</code> und <code>{B,C}</code> auf den äußeren P-Port <code>{A,B,C}</code> zusammenlaufen.</li>\n<li>Ein Assembly-Konnektor vom äußeren P-Port <code>{A,B,C}</code> zum externen R-Port <code>{A,B,C}</code>.</li>\n<li><strong>Bewertungssymbol</strong>: Smiley-Icon signalisiert Konformität und Zulässigkeit („legal“).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Beide internen Komponenten stellen Datenelemente bereit, die sich teilweise überlappen (Element <code>B</code> wird sowohl von der oberen als auch von der unteren Komponente gesendet). Da der äußere Port als <code>[nfold]</code> spezifiziert ist, ist die mehrfache Einspeisung desselben Datenelements (<code>B</code>) sowie die Zusammenführung der disjunkten Elemente <code>A</code> und <code>C</code> zulässig. Über den Assembly-Konnektor empfängt die externe Komponente alle Datenelemente <code>{A,B,C}</code>, wobei für Element <code>B</code> n-fache Sender-Semantik greift.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Zeigt die normative Ausprägung für <code>DelegationSwConnector</code> an Ports mit expliziter Mehrfachsender-Berechtigung (<code>[nfold]</code>). Im Gegensatz zu Single-Ports dürfen bei <code>[nfold]</code> mehrere interne Ports dasselbe Datenelement bereitstellen; das Modellierungswerkzeug muss den Merge als valide einstufen. Systemintegratoren müssen beachten, dass die Zielkomponente bzw. das zugrundeliegende RTE-/Kommunikationssubsystem für die Verarbeitung von Mehrfachsendern auf Datenelement <code>B</code> konfiguriert ist.</p>"}, {"id": "FIG-ae88f842042e84a5", "releases": ["R4.0.3", "R4.3.1", "R19-11", "R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">AUTOSAR-Komponentendiagramm / VFB-Architekturdiagramm im Kontext des AUTOSAR Software Component Template (TPS SoftwareComponentTemplate). Dargestellt wird die zulässige Zusammenführung von Delegationskonnektoren an einem äußeren P-Port mit <code>[single]</code>-Semantik, bei dem die internen Komponenten disjunkte Datenelementmengen bereitstellen, welche die Schnittstelle des äußeren Ports bilden.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Übergeordnete Komposition (<code>CompositionSwComponentType</code>)</strong>: Umschließt zwei interne Komponenten und besitzt einen äußeren P-Port mit der Schnittstellendefinition <code>{A,B,C}</code> und der Kennzeichnung <code>[single]</code>.</li>\n<li><strong>Interne Komponenten</strong>:</li>\n<li>Obere Komponente mit P-Port <code>{A,B}</code>.</li>\n<li>Untere Komponente mit P-Port <code>{C,D}</code>.</li>\n<li><strong>Externe Empfängerkomponente</strong>: Weist einen R-Port mit der Schnittstelle <code>{A,B,C}</code> auf.</li>\n<li><strong>Konnektoren</strong>:</li>\n<li>Zwei Delegationskonnektoren von den internen Ports <code>{A,B}</code> und <code>{C,D}</code> auf den äußeren P-Port <code>{A,B,C}</code>.</li>\n<li>Ein Assembly-Konnektor vom äußeren P-Port <code>{A,B,C}</code> zum externen R-Port <code>{A,B,C}</code>.</li>\n<li><strong>Bewertungssymbol</strong>: Smiley-Icon kennzeichnet die Konfiguration als zulässig.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die obere Komponente sendet <code>{A,B}</code>, die untere Komponente <code>{C,D}</code>. An der Kompositionsgrenze werden die Delegationspfade auf den P-Port <code>{A,B,C}</code> geführt. Da bezüglich der Schnittstelle des äußeren Ports jedes Element <code>{A, B, C}</code> genau eine eindeutige interne Quelle besitzt (<code>A</code> und <code>B</code> von oben, <code>C</code> von unten; das interne Element <code>D</code> verbleibt unverbunden bzw. wird am äußeren Port nicht exponiert) und kein Element doppelt bereitgestellt wird, ist die <code>[single]</code>-Bedingung erfüllt. Die Daten <code>{A,B,C}</code> werden über die Montageverbindung an den R-Port weitergeleitet.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Demonstriert die Regel, dass bei einem Delegations-Merge auf einen äußeren <code>[single]</code>-Port nicht zwingend alle Elemente eines internen Ports am äußeren Port exponiert werden müssen, solange bezüglich der Zielmenge <code>{A,B,C}</code> keine Überschneidung der Quellmengen vorliegt. Autorensysteme müssen validieren, dass die Schnittmenge der auf den äußeren Port abgebildeten Datenelemente leer ist, um Schreibkonflikte im Single-Sender-Paradigma auszuschließen.</p>"}, {"id": "FIG-8abd0c206d8525e1", "releases": ["R4.1.3", "R4.2.2", "R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">AUTOSAR-Komponentendiagramm / VFB-Architekturdiagramm im Kontext des AUTOSAR Software Component Template (TPS SoftwareComponentTemplate). Das Diagramm illustriert die zulässige Zusammenführung (Legal Merge) von Delegationskonnektoren (<code>DelegationSwConnector</code>) an einer Kompositionsgrenze (<code>CompositionSwComponentType</code>) hin zu einer externen Software-Komponente über einen <code>AssemblySwConnector</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Übergeordnete Komposition (<code>CompositionSwComponentType</code>)</strong>: Umschließt zwei interne Software-Komponenten-Prototypen und besitzt einen äußeren P-Port (<code>PPortPrototype</code>) mit der Daten-/Elementmenge <code>{A,B}</code> und der Eigenschaft <code>[single]</code>.</li>\n<li><strong>Interne Komponenten</strong>:</li>\n<li>Obere Komponente mit einem P-Port, der das Datenelement <code>{A}</code> bereitstellt.</li>\n<li>Untere Komponente mit einem P-Port, der das Datenelement <code>{B}</code> bereitstellt.</li>\n<li><strong>Externe Empfängerkomponente</strong>: Besitzt einen R-Port (<code>RPortPrototype</code>), der die Elementmenge <code>{A,B}</code> anfordert.</li>\n<li><strong>Konnektoren</strong>:</li>\n<li>Zwei interne Delegationskonnektoren (<code>DelegationSwConnector</code>), die von den internen Ports <code>{A}</code> bzw. <code>{B}</code> auf den gemeinsamen äußeren P-Port <code>{A,B}</code> gemergt werden.</li>\n<li>Ein Assembly-Konnektor (<code>AssemblySwConnector</code>), der den äußeren P-Port <code>{A,B}</code> mit dem externen R-Port <code>{A,B}</code> verbindet.</li>\n<li><strong>Bewertungssymbol</strong>: Ein Smiley-Icon symbolisiert die semantische und syntaktische Gültigkeit („legal“) dieser Konfiguration.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die internen Software-Komponenten senden disjunkte Teilmengen von Datenelementen (<code>{A}</code> bzw. <code>{B}</code>). Am gemeinsamen Port des umschließenden Typs werden diese Delegationen zu einer konsistenten Gesamtschnittstelle <code>{A,B}</code> zusammengeführt (<code>merge</code>). Von dort werden die aggregierten Daten über die Montageverbindung an die externe Empfängerkomponente weitergeleitet. Da die Elementmengen disjunkt sind (<code>{A} ∩ {B} = ∅</code>) und exakt der Schnittstelle des äußeren Single-Ports <code>{A,B}</code> entsprechen, tritt kein Schreibkonflikt auf.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Veranschaulicht die Regelungen für <code>DelegationSwConnector</code> an P-Ports mit <code>[single]</code>-Semantik. Ein Zusammenführen mehrerer Delegationspfade auf einen einzelnen äußeren P-Port ist zulässig, sofern jedes Datenelement der Port-Schnittstelle eindeutig durch genau eine interne Quelle bereitgestellt wird und die Vereinigung der internen Datenmengen die äußere Schnittstelle vollständig und überschneidungsfrei abdeckt. Entwickler und Autoren von AUTOSAR-Authoring-Tools müssen sicherstellen, dass bei <code>[single]</code> keine Mehrfachzuweisungen für identische Datenelemente innerhalb eines Merges entstehen.</p>"}, {"id": "FIG-64ba24e87ef15003", "releases": ["R4.1.3", "R4.2.2", "R4.3.1", "R19-11", "R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">AUTOSAR-Komponentendiagramm / VFB-Architekturdiagramm im Kontext des AUTOSAR Software Component Template (TPS SoftwareComponentTemplate). Das Diagramm stellt das zulässige Zusammenführen von Delegationskonnektoren (<code>DelegationSwConnector</code>) an einem äußeren P-Port mit <code>[nfold]</code>-Kommunikationssemantik innerhalb einer <code>CompositionSwComponentType</code> dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Übergeordnete Komposition (<code>CompositionSwComponentType</code>)</strong>: Umschließt zwei interne Komponenten und stellt einen äußeren P-Port mit der Elementmenge <code>{A,B,C}</code> und der Kennzeichnung <code>[nfold]</code> bereit.</li>\n<li><strong>Interne Komponenten</strong>:</li>\n<li>Obere Komponente mit P-Port <code>{A,B}</code>.</li>\n<li>Untere Komponente mit P-Port <code>{B,C}</code>.</li>\n<li><strong>Externe Empfängerkomponente</strong>: Besitzt einen R-Port mit der Schnittstelle <code>{A,B,C}</code>.</li>\n<li><strong>Konnektoren</strong>:</li>\n<li>Zwei Delegationskonnektoren, die von den internen P-Ports <code>{A,B}</code> und <code>{B,C}</code> auf den äußeren P-Port <code>{A,B,C}</code> zusammenlaufen.</li>\n<li>Ein Assembly-Konnektor vom äußeren P-Port <code>{A,B,C}</code> zum externen R-Port <code>{A,B,C}</code>.</li>\n<li><strong>Bewertungssymbol</strong>: Smiley-Icon signalisiert Konformität und Zulässigkeit („legal“).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Beide internen Komponenten stellen Datenelemente bereit, die sich teilweise überlappen (Element <code>B</code> wird sowohl von der oberen als auch von der unteren Komponente gesendet). Da der äußere Port als <code>[nfold]</code> spezifiziert ist, ist die mehrfache Einspeisung desselben Datenelements (<code>B</code>) sowie die Zusammenführung der disjunkten Elemente <code>A</code> und <code>C</code> zulässig. Über den Assembly-Konnektor empfängt die externe Komponente alle Datenelemente <code>{A,B,C}</code>, wobei für Element <code>B</code> n-fache Sender-Semantik greift.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Zeigt die normative Ausprägung für <code>DelegationSwConnector</code> an Ports mit expliziter Mehrfachsender-Berechtigung (<code>[nfold]</code>). Im Gegensatz zu Single-Ports dürfen bei <code>[nfold]</code> mehrere interne Ports dasselbe Datenelement bereitstellen; das Modellierungswerkzeug muss den Merge als valide einstufen. Systemintegratoren müssen beachten, dass die Zielkomponente bzw. das zugrundeliegende RTE-/Kommunikationssubsystem für die Verarbeitung von Mehrfachsendern auf Datenelement <code>B</code> konfiguriert ist.</p>"}, {"id": "FIG-fb9ad19553edeef5", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">AUTOSAR-Komponentendiagramm / VFB-Architekturdiagramm im Kontext des AUTOSAR Software Component Template (TPS SoftwareComponentTemplate). Dargestellt wird die zulässige Zusammenführung von Delegationskonnektoren an einem äußeren P-Port mit <code>[single]</code>-Semantik, bei dem die internen Komponenten disjunkte Datenelementmengen bereitstellen, welche die Schnittstelle des äußeren Ports bilden.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Übergeordnete Komposition (<code>CompositionSwComponentType</code>)</strong>: Umschließt zwei interne Komponenten und besitzt einen äußeren P-Port mit der Schnittstellendefinition <code>{A,B,C}</code> und der Kennzeichnung <code>[single]</code>.</li>\n<li><strong>Interne Komponenten</strong>:</li>\n<li>Obere Komponente mit P-Port <code>{A,B}</code>.</li>\n<li>Untere Komponente mit P-Port <code>{C,D}</code>.</li>\n<li><strong>Externe Empfängerkomponente</strong>: Weist einen R-Port mit der Schnittstelle <code>{A,B,C}</code> auf.</li>\n<li><strong>Konnektoren</strong>:</li>\n<li>Zwei Delegationskonnektoren von den internen Ports <code>{A,B}</code> und <code>{C,D}</code> auf den äußeren P-Port <code>{A,B,C}</code>.</li>\n<li>Ein Assembly-Konnektor vom äußeren P-Port <code>{A,B,C}</code> zum externen R-Port <code>{A,B,C}</code>.</li>\n<li><strong>Bewertungssymbol</strong>: Smiley-Icon kennzeichnet die Konfiguration als zulässig.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die obere Komponente sendet <code>{A,B}</code>, die untere Komponente <code>{C,D}</code>. An der Kompositionsgrenze werden die Delegationspfade auf den P-Port <code>{A,B,C}</code> geführt. Da bezüglich der Schnittstelle des äußeren Ports jedes Element <code>{A, B, C}</code> genau eine eindeutige interne Quelle besitzt (<code>A</code> und <code>B</code> von oben, <code>C</code> von unten; das interne Element <code>D</code> verbleibt unverbunden bzw. wird am äußeren Port nicht exponiert) und kein Element doppelt bereitgestellt wird, ist die <code>[single]</code>-Bedingung erfüllt. Die Daten <code>{A,B,C}</code> werden über die Montageverbindung an den R-Port weitergeleitet.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Demonstriert die Regel, dass bei einem Delegations-Merge auf einen äußeren <code>[single]</code>-Port nicht zwingend alle Elemente eines internen Ports am äußeren Port exponiert werden müssen, solange bezüglich der Zielmenge <code>{A,B,C}</code> keine Überschneidung der Quellmengen vorliegt. Autorensysteme müssen validieren, dass die Schnittmenge der auf den äußeren Port abgebildeten Datenelemente leer ist, um Schreibkonflikte im Single-Sender-Paradigma auszuschließen.</p>"}, {"id": "FIG-342c0f5e9fbee29f", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Informelles Komponentendiagramm im Kontext des AUTOSAR-Softwarekomponenten-Entwurfs (TPS Software Component Template). Es illustriert die strukturelle Zusammenführung (Merge) von Sender-Empfänger-Kommunikationspfaden über Delegationskonnektoren an der Begrenzung einer hierarchischen Komposition (Composition SwComponentType) hin zu einer externen Komponente.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm zeigt eine übergeordnete Kompositionskomponente, zwei darin gekapselte interne Softwarekomponenten (jeweils mit P-Port / Bereitstellungs-Port) sowie eine externe Empfängerkomponente (mit R-Port).</p>\n<ul class=\"fig-list\">\n<li>Oberer interner P-Port: deklariert die Datenelemente <code>{A, B}</code>.</li>\n<li>Unterer interner P-Port: deklariert die Datenelemente <code>{C, D}</code>.</li>\n<li>Begrenzungs-Port der Komposition (P-Port): vereinigt beide Delegationsverbindungen, annotiert mit <code>{A, B, C}</code> und der Eigenschaft <code>[single]</code>.</li>\n<li>Externer R-Port der Empfängerkomponente: annotiert mit <code>{A, B, C}</code>.</li>\n<li>Verbindungslinien: Zwei interne Delegationskonnektoren führen von den internen Ports zum Begrenzungs-Port; ein Assembly-Konnektor verbindet den Begrenzungs-Port mit dem externen Zielport.</li>\n<li>Ein Smiley-Symbol markiert die Konfiguration als zulässig.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Deklaration von Kommunikationspfaden für Sender-Receiver-Daten. Die internen Komponenten stellen jeweils Untermengen an Datenelementen bereit (<code>{A, B}</code> bzw. <code>{C, D}</code>). Am gemeinsamen Delegations-Ausgangsport werden die Teilmengen gebündelt an den Assembly-Konnektor übergeben, wobei die Schnittstelle des aggregierten Ports die Daten <code>{A, B, C}</code> umfasst und an den Empfänger transportiert. Element <code>D</code> verbleibt unverbunden bzw. wird nicht über diesen Begrenzungs-Port weitergeleitet.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Abbildung visualisiert ein zulässiges Entwurfsmuster („legal merge“) für Delegationskonnektoren mit <code>[single]</code>-Multiplizität. Es verdeutlicht, dass mehrere interne P-Ports über Delegation auf einen einzigen äußeren P-Port zusammengeführt werden dürfen, sofern die Datenelement-Mengen disjunkt bezüglich der übertragenen Signale sind bzw. keine semantischen Namens- oder Typkonflikte bei der Zusammenführung der Schnittstellenelemente auf <code>{A, B, C}</code> entstehen.</p>"}, {"id": "FIG-9629872b6b6ce0f8", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Informelles Komponentendiagramm im Kontext des AUTOSAR-Softwarekomponenten-Entwurfs (TPS Software Component Template). Es illustriert die zulässige Zusammenführung (Merge) von Datenflüssen aus mehreren internen Komponenten über Delegationskonnektoren an den Begrenzungs-Port einer Komposition hin zu einer externen Empfängerkomponente.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst eine umschließende Komposition mit Begrenzungs-Port, zwei interne Software-Komponenten sowie eine externe Empfänger-Komponente.</p>\n<ul class=\"fig-list\">\n<li>Oberer interner P-Port: deklariert das Datenelement <code>{A}</code>.</li>\n<li>Unterer interner P-Port: deklariert das Datenelement <code>{B}</code>.</li>\n<li>Begrenzungs-Port der Komposition (P-Port): bündelt beide Delegationskonnektoren, gekennzeichnet mit Datenelementen <code>{A, B}</code> und der Eigenschaft <code>[single]</code>.</li>\n<li>Externer R-Port: annotiert mit den Datenelementen <code>{A, B}</code>.</li>\n<li>Konnektoren: Zwei Delegationskonnektoren verbinden die internen P-Ports mit dem Begrenzungs-Port; ein Assembly-Konnektor verbindet diesen mit dem externen Port.</li>\n<li>Ein Smiley-Symbol weist die Konfiguration als gültig aus.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Modellierung eines Sender-Receiver-Schnittstellenmerges. Die zwei Quellkomponenten stellen disjunkte Datenelemente <code>{A}</code> und <code>{B}</code> bereit. Diese werden über Delegationskonnektoren am äußeren Schnittstellen-Port der Komposition zu einer gemeinsamen Schnittstelle <code>{A, B}</code> zusammengeführt und über den Assembly-Konnektor an die externe Empfängerkomponente übertragen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert eine normativ gültige Delegationsarchitektur für Einzelverbindungen (<code>[single]</code>). Eine Zusammenführung zweier interner P-Ports auf einen gemeinsamen P-Port ist zulässig, wenn jeder interne Port disjunkte Teilelemente (<code>{A}</code> bzw. <code>{B}</code>) der übergeordneten Port-Schnittstelle (<code>{A, B}</code>) bedient und keine Mehrfachzuweisung desselben Datenelements vorliegt.</p>"}, {"id": "FIG-d45b2282dca3d20e", "releases": ["R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Informelles Komponentendiagramm im Kontext des AUTOSAR-Softwarekomponenten-Entwurfs (TPS Software Component Template). Es visualisiert ein Entwurfsszenario für die Zusammenführung (Merge) von Delegationskonnektoren an der Portgrenze einer Komposition hin zu einer externen Komponente.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm zeigt eine Komposition mit zwei internen Software-Komponenten, einen Begrenzungs-Port sowie eine externe Komponente.</p>\n<ul class=\"fig-list\">\n<li>Oberer interner P-Port: annotiert mit <code>{A, B}</code>.</li>\n<li>Unterer interner P-Port: annotiert mit <code>{B, C}</code>.</li>\n<li>Begrenzungs-Port der Komposition (P-Port): Ziel beider Delegationskonnektoren, annotiert mit <code>{A, B, C}</code> und der Eigenschaft <code>[nfold]</code>.</li>\n<li>Externer R-Port: deklariert mit <code>{A, B, C}</code>.</li>\n<li>Verbindungen: Zwei Delegationskonnektoren führen von den internen Ports zum Begrenzungs-Port; ein Assembly-Konnektor verbindet den Begrenzungs-Port mit der externen Komponente.</li>\n<li>Ein Smiley-Symbol kennzeichnet das Konstrukt als zulässig.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Modellierung einer überlappenden Schnittstellendelegation. Die beiden internen Komponenten stellen Datenelementmengen bereit, die ein gemeinsames Element aufweisen (<code>{A, B}</code> und <code>{B, C}</code>). Durch die mehrfache Belegung (<code>[nfold]</code>) wird die Zusammenführung am Begrenzungs-Port für das Gesamtspektrum <code>{A, B, C}</code> ermöglicht und an den Empfänger weitergeleitet.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm veranschaulicht die Zulässigkeit des Delegations-Merges bei nicht-disjunkten Datenelementmengen (gemeinsames Element <code>B</code>), vorausgesetzt, der Begrenzungs-Port ist für mehrfache Anbindung (<code>[nfold]</code>) qualifiziert. Entwickler müssen bei <code>[nfold]</code>-Konnektoren sicherstellen, dass die Semantik mehrfacher Bereitsteller für identische Datenelemente im Systementwurf gewollt und spezifikationskonform ist.</p>"}, {"id": "FIG-40dff9323d1b749a", "releases": ["R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Informelles Komponentendiagramm im Kontext des AUTOSAR-Softwarekomponenten-Entwurfs (TPS Software Component Template). Es illustriert die strukturelle Zusammenführung (Merge) von Sender-Empfänger-Kommunikationspfaden über Delegationskonnektoren an der Begrenzung einer hierarchischen Komposition (Composition SwComponentType) hin zu einer externen Komponente.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm zeigt eine übergeordnete Kompositionskomponente, zwei darin gekapselte interne Softwarekomponenten (jeweils mit P-Port / Bereitstellungs-Port) sowie eine externe Empfängerkomponente (mit R-Port).</p>\n<ul class=\"fig-list\">\n<li>Oberer interner P-Port: deklariert die Datenelemente <code>{A, B}</code>.</li>\n<li>Unterer interner P-Port: deklariert die Datenelemente <code>{C, D}</code>.</li>\n<li>Begrenzungs-Port der Komposition (P-Port): vereinigt beide Delegationsverbindungen, annotiert mit <code>{A, B, C}</code> und der Eigenschaft <code>[single]</code>.</li>\n<li>Externer R-Port der Empfängerkomponente: annotiert mit <code>{A, B, C}</code>.</li>\n<li>Verbindungslinien: Zwei interne Delegationskonnektoren führen von den internen Ports zum Begrenzungs-Port; ein Assembly-Konnektor verbindet den Begrenzungs-Port mit dem externen Zielport.</li>\n<li>Ein Smiley-Symbol markiert die Konfiguration als zulässig.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Deklaration von Kommunikationspfaden für Sender-Receiver-Daten. Die internen Komponenten stellen jeweils Untermengen an Datenelementen bereit (<code>{A, B}</code> bzw. <code>{C, D}</code>). Am gemeinsamen Delegations-Ausgangsport werden die Teilmengen gebündelt an den Assembly-Konnektor übergeben, wobei die Schnittstelle des aggregierten Ports die Daten <code>{A, B, C}</code> umfasst und an den Empfänger transportiert. Element <code>D</code> verbleibt unverbunden bzw. wird nicht über diesen Begrenzungs-Port weitergeleitet.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Abbildung visualisiert ein zulässiges Entwurfsmuster („legal merge“) für Delegationskonnektoren mit <code>[single]</code>-Multiplizität. Es verdeutlicht, dass mehrere interne P-Ports über Delegation auf einen einzigen äußeren P-Port zusammengeführt werden dürfen, sofern die Datenelement-Mengen disjunkt bezüglich der übertragenen Signale sind bzw. keine semantischen Namens- oder Typkonflikte bei der Zusammenführung der Schnittstellenelemente auf <code>{A, B, C}</code> entstehen.</p>"}, {"id": "FIG-eaf7a23452625fbe", "releases": ["R19-11", "R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Informelles Komponentendiagramm im Kontext des AUTOSAR-Softwarekomponenten-Entwurfs (TPS Software Component Template). Es illustriert die zulässige Zusammenführung (Merge) von Datenflüssen aus mehreren internen Komponenten über Delegationskonnektoren an den Begrenzungs-Port einer Komposition hin zu einer externen Empfängerkomponente.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst eine umschließende Komposition mit Begrenzungs-Port, zwei interne Software-Komponenten sowie eine externe Empfänger-Komponente.</p>\n<ul class=\"fig-list\">\n<li>Oberer interner P-Port: deklariert das Datenelement <code>{A}</code>.</li>\n<li>Unterer interner P-Port: deklariert das Datenelement <code>{B}</code>.</li>\n<li>Begrenzungs-Port der Komposition (P-Port): bündelt beide Delegationskonnektoren, gekennzeichnet mit Datenelementen <code>{A, B}</code> und der Eigenschaft <code>[single]</code>.</li>\n<li>Externer R-Port: annotiert mit den Datenelementen <code>{A, B}</code>.</li>\n<li>Konnektoren: Zwei Delegationskonnektoren verbinden die internen P-Ports mit dem Begrenzungs-Port; ein Assembly-Konnektor verbindet diesen mit dem externen Port.</li>\n<li>Ein Smiley-Symbol weist die Konfiguration als gültig aus.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Modellierung eines Sender-Receiver-Schnittstellenmerges. Die zwei Quellkomponenten stellen disjunkte Datenelemente <code>{A}</code> und <code>{B}</code> bereit. Diese werden über Delegationskonnektoren am äußeren Schnittstellen-Port der Komposition zu einer gemeinsamen Schnittstelle <code>{A, B}</code> zusammengeführt und über den Assembly-Konnektor an die externe Empfängerkomponente übertragen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert eine normativ gültige Delegationsarchitektur für Einzelverbindungen (<code>[single]</code>). Eine Zusammenführung zweier interner P-Ports auf einen gemeinsamen P-Port ist zulässig, wenn jeder interne Port disjunkte Teilelemente (<code>{A}</code> bzw. <code>{B}</code>) der übergeordneten Port-Schnittstelle (<code>{A, B}</code>) bedient und keine Mehrfachzuweisung desselben Datenelements vorliegt.</p>"}, {"id": "FIG-17c12d4806f30498", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Informelles Komponentendiagramm im Kontext des AUTOSAR-Softwarekomponenten-Entwurfs (TPS Software Component Template). Es illustriert die zulässige Zusammenführung (Merge) von Datenflüssen aus mehreren internen Komponenten über Delegationskonnektoren an den Begrenzungs-Port einer Komposition hin zu einer externen Empfängerkomponente.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst eine umschließende Komposition mit Begrenzungs-Port, zwei interne Software-Komponenten sowie eine externe Empfänger-Komponente.</p>\n<ul class=\"fig-list\">\n<li>Oberer interner P-Port: deklariert das Datenelement <code>{A}</code>.</li>\n<li>Unterer interner P-Port: deklariert das Datenelement <code>{B}</code>.</li>\n<li>Begrenzungs-Port der Komposition (P-Port): bündelt beide Delegationskonnektoren, gekennzeichnet mit Datenelementen <code>{A, B}</code> und der Eigenschaft <code>[single]</code>.</li>\n<li>Externer R-Port: annotiert mit den Datenelementen <code>{A, B}</code>.</li>\n<li>Konnektoren: Zwei Delegationskonnektoren verbinden die internen P-Ports mit dem Begrenzungs-Port; ein Assembly-Konnektor verbindet diesen mit dem externen Port.</li>\n<li>Ein Smiley-Symbol weist die Konfiguration als gültig aus.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Modellierung eines Sender-Receiver-Schnittstellenmerges. Die zwei Quellkomponenten stellen disjunkte Datenelemente <code>{A}</code> und <code>{B}</code> bereit. Diese werden über Delegationskonnektoren am äußeren Schnittstellen-Port der Komposition zu einer gemeinsamen Schnittstelle <code>{A, B}</code> zusammengeführt und über den Assembly-Konnektor an die externe Empfängerkomponente übertragen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert eine normativ gültige Delegationsarchitektur für Einzelverbindungen (<code>[single]</code>). Eine Zusammenführung zweier interner P-Ports auf einen gemeinsamen P-Port ist zulässig, wenn jeder interne Port disjunkte Teilelemente (<code>{A}</code> bzw. <code>{B}</code>) der übergeordneten Port-Schnittstelle (<code>{A, B}</code>) bedient und keine Mehrfachzuweisung desselben Datenelements vorliegt.</p>"}, {"id": "FIG-d8369d99cb8c7eda", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Komponentendiagramm im Kontext des AUTOSAR-Softwarekomponenten-Templates (<code>AUTOSAR_TPS_SoftwareComponentTemplate</code>). Das Diagramm visualisiert die strukturelle Zusammenführung (Merge) von <code>DelegationSwConnector</code>-Instanzen an der Begrenzung einer <code>CompositionSwComponentType</code> hin zu einem gemeinsamen äußeren <code>PPortPrototype</code> sowie die anschließende <code>AssemblySwConnector</code>-Verbindung zu einer externen Komponente.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm zeigt eine übergeordnete Kompositionskomponente (<code>CompositionSwComponentType</code>) mit zwei internen Software-Komponentenprototypen (<code>SwComponentPrototype</code>). Beide inneren Komponenten besitzen je einen <code>PPortPrototype</code> (Sender- bzw. Provider-Port):</p>\n<ul class=\"fig-list\">\n<li>Der obere innere Port stellt das Datenelement- bzw. Interface-Set <code>{A, B}</code> bereit.</li>\n<li>Der untere innere Port stellt das Datenelement- bzw. Interface-Set <code>{B, C}</code> bereit.</li>\n</ul>\n<p class=\"fig-p\">An der Außenhülle der Komposition befindet sich ein aggregierender <code>PPortPrototype</code>, der mit <code>{A, B, C}</code> annotiert und als <code>[nfold]</code> gekennzeichnet ist. Zwei <code>DelegationSwConnector</code>-Verbindungen führen von den inneren Ports zu diesem äußeren Port. Von dort verbindet ein <code>AssemblySwConnector</code> den äußeren Port mit einem <code>RPortPrototype</code> (Empfänger- bzw. Requirer-Port) einer externen Software-Komponente, der ebenfalls für <code>{A, B, C}</code> typisiert ist. Ein Smiley-Symbol markiert die Zulässigkeit dieser Konfiguration.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Konnektorkonfiguration zur Datenweiterleitung: Mehrere interne Komponenteninstanzen senden über ihre jeweiligen Provider-Ports voneinander überlappende Teilmengen (<code>{A, B}</code> und <code>{B, C}</code>) der im Gesamtschnittstellentyp definierten Datenelemente bzw. Operationen. An der Kompositionsgrenze werden die Datenströme über Delegationskonnektoren auf einen gemeinsamen Delegationsport gemergt. Durch das Kommunikationsmuster bzw. die Port-Eigenschaft <code>[nfold]</code> (Mehrfach- bzw. n-fache Delegation) wird der parallele Empfang und die Bereitstellung der kombinierten Menge <code>{A, B, C}</code> für nachgelagerte Komponenten über die Assembly-Verbindung ermöglicht. Datenelement <code>B</code> wird dabei von beiden inneren Sendern bereitgestellt.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ relevanter Anwendungsfall für einen zulässigen Merge von Delegationskonnektoren (Delegation Connector Merge). Wenn ein aggregierender Delegations-Port als <code>[nfold]</code> ausgelegt ist, dürfen mehrere interne Provider-Ports auf denselben äußeren Delegationsport geführt werden, selbst wenn sie identische Datenelemente (hier Datenelement <code>B</code>) bereitstellen. Die Schnittstelle des äußeren Delegationsports muss mindestens die Vereinigungsmenge der transportierten Daten-/Interface-Elemente abdecken (<code>{A, B, C}</code>). Integratoren und Modellierer müssen sicherstellen, dass bei n-facher Belegung Namens- und Datentyphomogenität gewahrt bleiben und Mehrfachsendungen auf gemeinsam genutzten Elementen deterministisch verarbeitet werden.</p>"}, {"id": "FIG-0a95bc5f9bf60d6c", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Komponentendiagramm im Kontext des AUTOSAR-Softwarekomponenten-Templates (<code>AUTOSAR_TPS_SoftwareComponentTemplate</code>). Das Diagramm stellt eine Konfiguration zur Zusammenführung (Merge) von <code>DelegationSwConnector</code>-Instanzen an der Systemgrenze einer <code>CompositionSwComponentType</code> dar, die über einen <code>AssemblySwConnector</code> an eine externe Empfängerkomponente angebunden ist.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Dargestellt ist eine umschließende <code>CompositionSwComponentType</code> mit zwei internen <code>SwComponentPrototype</code>-Instanzen. Beide inneren Komponenten besitzen je einen <code>PPortPrototype</code>:</p>\n<ul class=\"fig-list\">\n<li>Der obere interne Port stellt die Datenelemente bzw. Interfaces <code>{A, B}</code> bereit.</li>\n<li>Der untere interne Port stellt die Datenelemente bzw. Interfaces <code>{C, D}</code> bereit.</li>\n</ul>\n<p class=\"fig-p\">Auf der Begrenzung der Komposition befindet sich ein <code>PPortPrototype</code>, annotiert mit <code>{A, B, C}</code> und der Eigenschaft <code>[single]</code>. Zwei <code>DelegationSwConnector</code>-Linien konvergieren von den beiden internen Ports auf diesen äußeren Port. Ein <code>AssemblySwConnector</code> führt vom äußeren Port zum <code>RPortPrototype</code> einer externen Software-Komponente mit Interface <code>{A, B, C}</code>. Die Darstellung ist mit einem Smiley-Symbol versehen.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statischer Konnektions- und Signalleitungsfluss: Zwei interne Komponenten führen ihre separaten Datenmengen <code>{A, B}</code> und <code>{C, D}</code> über getrennte Delegationskonnektoren an einem einzelnen äußeren Port zusammen. Der äußere Port leitet die definierten Schnittstellenelemente <code>{A, B, C}</code> im Rahmen einer Single-Delegation (<code>[single]</code>) über den Assembly-Konnektor an die externe Empfängerkomponente weiter. Datenelement <code>D</code> aus dem unteren internen Port ist im äußeren Port nicht enthalten.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Konstruktionsbeispiel für das Zusammenführen disjunkter Teilschnittstellen auf einen <code>[single]</code>-Delegationsport. Für die Konformität der Schnittstellendefinition ist die Verträglichkeit der beteiligten Port-Interfaces entscheidend: Der äußere Port aggregiert die erforderlichen Elemente <code>{A, B, C}</code>, während nicht im äußeren Interface definierte Elemente (wie <code>D</code>) nicht nach außen exponiert werden. Entwickler müssen bei <code>[single]</code>-Verbindungen prüfen, ob ein echter Merge oder eine disjunkte Zusammensetzung vorliegt und ob alle vom Assembly-Partner erwarteten Elemente konsistent bedient werden.</p>"}], "trans": []};
